function renderProducts(){
 const list=products.filter(p=>(activeCat==="all"||p.cat===activeCat)&&((p.name[lang]+" "+p.desc[lang]+" "+p.query).toLowerCase().includes(query.toLowerCase())));
 $("grid").innerHTML=list.length?list.map(p=>{
  const photo=productPhotos[p.id];
  const poster=photo?'<img class="product-photo" src="'+photo+'" alt="'+p.name[lang]+'" loading="lazy" decoding="async"><div class="poster-art" hidden>'+posterSVG(p.id,p.cat)+'</div>':'<div class="poster-art">'+posterSVG(p.id)+'</div>';
  return '<article class="product"><div class="visual">'+poster+'<span class="tag">'+(lang==="ar"?(p.tagAr||p.tag):p.tag)+'</span></div><h3>'+p.name[lang]+'</h3><p class="desc">'+p.desc[lang]+'</p><div class="price">'+(lang==="en"?"Check current price":"تحقّق من السعر")+'</div><a class="buy" href="'+amazonUrl(p.query)+'" target="_blank" rel="noopener noreferrer" aria-label="'+(lang==="en"?"Find ":"ابحث عن ")+p.name[lang]+' on Amazon.ae"><span>'+(lang==="en"?"View on Amazon.ae":"عرض في Amazon.ae")+'</span><span aria-hidden="true">↗</span></a></article>';
 }).join(""):'<p class="empty">'+(lang==="en"?"No matching accessories. Try another search.":"لا توجد إكسسوارات مطابقة. جرّب البحث بكلمات أخرى.")+'</p>';
 $("grid").querySelectorAll(".product-photo").forEach(img=>img.addEventListener("error",()=>{img.hidden=true;const fallback=img.nextElementSibling;if(fallback)fallback.hidden=false},{once:true}));
}function setLang(next){lang=next;document.documentElement.lang=lang;document.documentElement.dir=lang==="ar"?"rtl":"ltr";$("enBtn").classList.toggle("active",lang==="en");$("arBtn").classList.toggle("active",lang==="ar");$("enBtn").setAttribute("aria-pressed",String(lang==="en"));$("arBtn").setAttribute("aria-pressed",String(lang==="ar"));document.querySelectorAll("[data-en][data-ar]").forEach(el=>el.innerHTML=el.dataset[lang]);$("search").placeholder=$("search").dataset["placeholder"+(lang==="en"?"En":"Ar")];$("search").setAttribute("aria-label",lang==="en"?"Search products":"ابحث عن المنتجات");renderFilters();renderProducts()}
$("enBtn").addEventListener("click",()=>location.assign("/"));$("arBtn").addEventListener("click",()=>location.assign("/ar/"));$("search").addEventListener("input",e=>{query=e.target.value;renderProducts()});$("search").addEventListener("search",e=>{query=e.target.value;renderProducts()});$("year").textContent=new Date().getFullYear();setLang(lang);
